package org.example.moderation;

import org.example.auth.AuthenticatedMember;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.Clock;
import java.time.LocalDateTime;
import java.time.temporal.ChronoUnit;
import java.util.List;

@Service
public class BannedWordService {

    private final BannedWordMapper bannedWordMapper;
    private final Clock clock;

    public BannedWordService(BannedWordMapper bannedWordMapper, Clock clock) {
        this.bannedWordMapper = bannedWordMapper;
        this.clock = clock;
    }

    @Transactional(readOnly = true)
    public List<BannedWordResponse> list() {
        return bannedWordMapper.findAll().stream()
                .map(w -> new BannedWordResponse(w.id(), w.word(), w.action()))
                .toList();
    }

    // 중복은 409 — 대소문자만 다른 것도 같은 단어로 본다(utf8mb4_0900_ai_ci 비교 + UNIQUE)
    @Transactional
    public BannedWordResponse add(AuthenticatedMember me, BannedWordRequest request) {
        String word = request.word().strip();
        if (bannedWordMapper.existsByWord(word)) {
            throw new DuplicateBannedWordException();
        }
        try {
            BannedWordWrite command = new BannedWordWrite(word, request.action(), me.id(),
                    LocalDateTime.now(clock).truncatedTo(ChronoUnit.SECONDS));
            bannedWordMapper.insert(command);
            return new BannedWordResponse(command.getId(), word, request.action());
        } catch (DataIntegrityViolationException e) {
            throw new DuplicateBannedWordException();
        }
    }

    @Transactional
    public void delete(Long id) {
        if (bannedWordMapper.delete(id) != 1) {
            throw new BannedWordNotFoundException();
        }
    }
}

